import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, UseInterceptors } from "@nestjs/common"
import { tap } from "rxjs"

@Injectable()
class HelloInterceptor implements NestInterceptor {
    intercept(_ctx: ExecutionContext, next: CallHandler) {
        console.log("Controller'dan OLDIN")
        return next.handle().pipe(tap(() => console.log("Controller'dan KEYIN")))
    }
}

@Controller("hello")
@UseInterceptors(HelloInterceptor)
class HelloController {
    @Get() hello() { console.log("Controller ishlayapti"); return "salom" }
}

@Module({ controllers: [HelloController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/hello")
    await http.close()
}
