import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, UseInterceptors } from "@nestjs/common"
import { tap } from "rxjs"

@Injectable()
class StatsService {
    hits = new Map<string, number>()
    hit(route: string) { this.hits.set(route, (this.hits.get(route) ?? 0) + 1) }
}

@Injectable()
class StatsInterceptor implements NestInterceptor {
    constructor(private readonly stats: StatsService) {}
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const route = ctx.getHandler().name
        return next.handle().pipe(tap(() => this.stats.hit(route)))
    }
}

@Controller()
@UseInterceptors(StatsInterceptor)
class AppController {
    constructor(private readonly stats: StatsService) {}
    @Get("a") a() { return "a" }
    @Get("b") b() { return "b" }
    @Get("stats") show() { return Object.fromEntries(this.stats.hits) }
}

@Module({ controllers: [AppController], providers: [StatsService] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/a"); await http.get("/a"); await http.get("/b")
    await http.get("/stats")
    await http.close()
}
main()

