import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, UseInterceptors } from "@nestjs/common"
import { map } from "rxjs"

const normalize = (v: unknown): unknown =>
    typeof v === "bigint" ? v.toString()
    : v instanceof Date ? v.toISOString().slice(0, 10)
    : Array.isArray(v) ? v.map(normalize)
    : v && typeof v === "object" ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, normalize(x)]))
    : v

@Injectable()
class NormalizeInterceptor implements NestInterceptor {
    intercept(_ctx: ExecutionContext, next: CallHandler) { return next.handle().pipe(map(normalize)) }
}

