import { CallHandler, ExecutionContext, Injectable, NestInterceptor } from "@nestjs/common"
import { firstValueFrom, map, of } from "rxjs"
import assert from "node:assert/strict"

@Injectable()
class WrapInterceptor implements NestInterceptor {
    intercept(_ctx: ExecutionContext, next: CallHandler) { return next.handle().pipe(map(data => ({ data, ok: true }))) }
}

async function main() {
    const handler: CallHandler = { handle: () => of([1, 2, 3]) }
    const result = await firstValueFrom(new WrapInterceptor().intercept({} as ExecutionContext, handler))
    assert.deepEqual(result, { data: [1, 2, 3], ok: true })
    console.log("✔", result)
}
main()

import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, SetMetadata } from "@nestjs/common"
import { APP_INTERCEPTOR, Reflector } from "@nestjs/core"
import { map } from "rxjs"

const SkipWrap = () => SetMetadata("skipWrap", true)

@Injectable()
class WrapInterceptor implements NestInterceptor {
    constructor(private readonly reflector: Reflector) {}
    intercept(ctx: ExecutionContext, next: CallHandler) {
        if (this.reflector.get<boolean>("skipWrap", ctx.getHandler())) return next.handle()
        return next.handle().pipe(map(data => ({ data })))
    }
}

@Controller()
class AppController {
    @Get("users") users() { return ["Ali"] }
    @Get("health") @SkipWrap() health() { return "ok" }   // monitoring toza javob kutadi
}
@Module({ controllers: [AppController], providers: [{ provide: APP_INTERCEPTOR, useClass: WrapInterceptor }] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/users")
    await http.get("/health")
    await http.close()
}
main()

import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, ServiceUnavailableException, UseInterceptors } from "@nestjs/common"
import { defer, retry } from "rxjs"

@Injectable()
class RetryInterceptor implements NestInterceptor {
    intercept(_ctx: ExecutionContext, next: CallHandler) {
        return defer(() => next.handle()).pipe(retry({ count: 2, delay: 10 }))
    }
}

