@Injectable()
class AuditService {
    entries: string[] = []
    add(e: string) { this.entries.push(e) }
}

@Injectable()
class AuditInterceptor implements NestInterceptor {
    constructor(private readonly audit: AuditService) {}
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const req = ctx.switchToHttp().getRequest()
        const who = req.headers["x-user"] ?? "anonim"
        return next.handle().pipe(tap(() =>
            this.audit.add(`${who}: ${req.method} ${req.url} ${JSON.stringify(req.body ?? {})}`)))
    }
}

@Controller("products")
@UseInterceptors(AuditInterceptor)
class ProductsController {
    @Patch(":id") update(@Param("id") id: string, @Body() b: any) { return { id, ...b } }
    @Delete(":id") remove(@Param("id") id: string) { return { removed: id } }
}

