import { CallHandler, Controller, ExecutionContext, Get, Injectable, Module, NestInterceptor, UseInterceptors } from "@nestjs/common"
import { of, tap } from "rxjs"

@Injectable()
class TtlCacheInterceptor implements NestInterceptor {
    private cache = new Map<string, { value: unknown; expires: number }>()
    private ttl = 50
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const key = ctx.switchToHttp().getRequest().url
        const hit = this.cache.get(key)
        if (hit && hit.expires > Date.now()) return of({ ...(hit.value as object), fromCache: true })
        return next.handle().pipe(tap(value => this.cache.set(key, { value, expires: Date.now() + this.ttl })))
    }
}

